 $pdo->exec("CREATE TABLE IF NOT EXISTS pppoe_health_alert_state (router_id INT NOT NULL,username VARCHAR(128) NOT NULL,current_level VARCHAR(16) NOT NULL DEFAULT 'normal',current_score INT NOT NULL DEFAULT 100,last_notified_level VARCHAR(16) NULL,last_notified_at DATETIME NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(router_id,username),KEY idx_health_level(router_id,current_level)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $reserve=$pdo->prepare('INSERT IGNORE INTO telegram_pppoe_disconnect_log(event_key,router_id,username,session_id) VALUES(?,?,?,?)');$remove=$pdo->prepare('DELETE FROM telegram_pppoe_disconnect_log WHERE event_key=?');
