 }
 echo json_encode(['success'=>true,'sent'=>$sent,'skipped'=>$skipped,'logged'=>$logged,'health_alerts'=>$healthAlerts,'reconnect_sent'=>$reconnectSent,'errors'=>$errors],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
